      try {
        const mediaId = await uploadPhoto(file, eventId, token);
        setPhotos((p) => [...p, { mediaId: mediaId as Id<"media">, name: file.name }]);
      } catch (e) {
        toast.error(e instanceof Error ? e.message : "Upload failed");
      }
    }
    setUploading(false);
  }

  if (full) {
    return (
